<?php
require 'config.php'; require_role('student'); $title='Subject Details'; $id=(int)($_GET['id']??0);
$q=$pdo->prepare("SELECT s.*,u.name faculty_name FROM subjects s LEFT JOIN users u ON u.id=s.faculty_id WHERE s.id=?");$q->execute([$id]);$subject=$q->fetch();
$offers=[];if($subject){$q=$pdo->prepare("SELECT o.*,u.name faculty_name FROM subject_offerings o LEFT JOIN users u ON u.id=o.faculty_id WHERE o.subject_id=? ORDER BY FIELD(o.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),o.start_time");$q->execute([$id]);$offers=$q->fetchAll();}
require 'header.php';?>
<div class="section"><a class="back-link" href="enrollment.php">← Back to Enrollment</a><?php if(!$subject):?><p class="muted">Subject not found.</p><?php else:?><div class="subject-detail-head"><div><span class="eyebrow">SUBJECT INFORMATION</span><h2><?=e($subject['code'])?> — <?=e($subject['name'])?></h2><p class="muted"><?=e($subject['units'])?> units · Section <?=e($subject['section']?:'Multiple Sections')?></p></div><a class="btn" href="enrollment.php">Choose a Schedule</a></div><div class="subject-detail-grid"><div><span>Description</span><p><?=e($subject['description']?:'No description has been provided for this subject.')?></p></div><div><span>Prerequisite</span><p><?=e($subject['prerequisite']?:'None')?></p></div><div><span>Department / Program</span><p><?=e($_SESSION['user']['program']?:'Program not set')?></p></div><div><span>Default Faculty</span><p><?=e($subject['faculty_name']?:'Assigned by Administration')?></p></div></div><h3 class="subsection-title">Available Schedules & Teachers</h3><?php foreach($offers as $o):?><div class="detail-offering"><b><?=e($o['day_name'])?></b><span><?=date('g:i A',strtotime($o['start_time']))?> – <?=date('g:i A',strtotime($o['end_time']))?></span><span><?=e($o['faculty_name']?:'Assigned Faculty')?></span><span>Section <?=e($o['section'])?> · <?=e($o['room'])?></span></div><?php endforeach;?></div><?php endif;?></div><?php require 'footer.php';?>
